1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	const FIRST_INSURANCE_SURCHARGE = 0.1;
58	
59	const CURSE_SURCHARGE = 0.5;
60	
61	const HIGH_ENCHANTMENT_LEVEL = 5;
62	
63	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
64	
65	const LOYALTY_YEARS = 2;
66	
67	const LOYALTY_DISCOUNT = 0.2;
68	
69	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
70	
71	const BASE_PREMIUMS: Record<string, number> = {
72	  sword: 100,
73	  amulet: 60,
74	  staff: 80,
75	  potion: 40,
76	  rune: 25,
77	  moonstone: 25,
78	};
79	
80	const INSURANCE_VALUES: Record<string, number> = {
81	  sword: 1000,
82	  amulet: 600,
83	  staff: 800,
84	  potion: 400,
85	  rune: 250,
86	  moonstone: 250,
87	};
88	
89	const DEDUCTIBLE = 100;
90	
91	const HALVED_PAYOUT_ENCHANTMENT = 8;
92	
93	const HALVED_PAYOUT_RATE = 0.5;
94	
95	const CAP_MULTIPLIER = 2;
96	
97	const BLOCK_SIZE = 3;
98	
99	const BLOCK_BASE_PREMIUM = 60;
100	
101	const countsByType = (items: Item[]): Map<string, number> => {
102	  const counts = new Map<string, number>();
103	
104	  for (const item of items) {
105	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
106	  }
107	
108	  return counts;
109	};
110	
111	const typeBasePremium = (type: string, count: number): number =>
112	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
113	
114	const policyBasePremium = (items: Item[]): number =>
115	  [...countsByType(items)].reduce(
116	    (total, [type, count]) => total + typeBasePremium(type, count),
117	    0,
118	  );
119	
120	// Modifiers below all express a rate applied to some base. Keep every one of
121	// them in the form `base + base * RATE`. The algebraically equivalent
122	// `base * (1 + RATE)` is NOT safe here: 100 * 1.1 === 110.00000000000001 in
123	// IEEE-754, and Math.ceil turns that into 116 instead of 115. Ceil amplifies
124	// upward float error rather than absorbing it.
125	
126	// Item-specific modifiers: each is computed on the affected item's OWN base
127	// premium, then summed across items. Note this is the item's UNIT base premium
128	// — never the block-adjusted one. A rune inside a block of 3 is still
129	// surcharged on its own 25 G, not on its 20 G share of the block.
130	const unitBasePremium = (item: Item): number => BASE_PREMIUMS[item.type];
131	
132	const isHighlyEnchanted = (item: Item): boolean =>
133	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
134	
135	const itemSurchargeRate = (item: Item): number =>
136	  (item.cursed ? CURSE_SURCHARGE : 0) +
137	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE : 0);
138	
139	const itemSurcharges = (items: Item[]): number =>
140	  items.reduce(
141	    (total, item) => total + unitBasePremium(item) * itemSurchargeRate(item),
142	    0,
143	  );
144	
145	// Policy-wide modifiers: each is computed on the policy base premium (the sum
146	// of all item base premiums), independent of which items make it up.
147	const isLoyal = (customer: Customer): boolean =>
148	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
149	
150	const policyModifierRate = (
151	  customer: Customer,
152	  isFollowUpContract: boolean,
153	): number =>
154	  FIRST_INSURANCE_SURCHARGE -
155	  (isLoyal(customer) ? LOYALTY_DISCOUNT : 0) -
156	  (isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT : 0);
157	
158	const quote = (
159	  items: Item[],
160	  customer: Customer,
161	  isFollowUpContract: boolean,
162	): QuoteResult => {
163	  const policyBase = policyBasePremium(items);
164	  const policyModifiers =
165	    policyBase * policyModifierRate(customer, isFollowUpContract);
166	
167	  return {
168	    premium: Math.ceil(
169	      policyBase + itemSurcharges(items) + policyModifiers + PROCESSING_FEE,
170	    ),
171	  };
172	};
173	
174	interface Policy {
175	  items: Item[];
176	  remainingCap: number;
177	}
178	
179	const insuranceSum = (items: Item[]): number =>
180	  items.reduce((total, item) => total + INSURANCE_VALUES[item.type], 0);
181	
182	const openPolicy = (items: Item[]): Policy => ({
183	  items,
184	  remainingCap: insuranceSum(items) * CAP_MULTIPLIER,
185	});
186	
187	// Each damage entry carries its own deductible: an incident that harms three
188	// insured items subtracts the deductible three times, not once. The
189	// reimbursement rate depends on the damaged item, so the item is looked up in
190	// the policy. Note this enchantment threshold (8) is the CLAIM rule and is
191	// distinct from HIGH_ENCHANTMENT_LEVEL (5), which is the premium rule.
192	const reimbursementRate = (item: Item): number =>
193	  (item.enchantment ?? 0) >= HALVED_PAYOUT_ENCHANTMENT ? HALVED_PAYOUT_RATE : 1;
194	
195	const reimbursement = (damage: Damage, item: Item): number =>
196	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
197	
198	// Payouts round DOWN where premiums round UP — both in the MHPCO's favour.
199	// Round once, here, so the figure reported to the customer and the figure
200	// charged against the cap can never drift apart.
201	const claim = (policy: Policy, incident: Incident): ClaimResult => {
202	  const payout = Math.floor(
203	    incident.damages.reduce(
204	      (total, damage) =>
205	        total +
206	        reimbursement(
207	          damage,
208	          policy.items.find((item) => item.type === damage.itemType)!,
209	        ),
210	      0,
211	    ),
212	  );
213	
214	  policy.remainingCap -= payout;
215	
216	  return { payout, remainingCap: policy.remainingCap };
217	};
218	
219	export const runScenario = (scenario: Scenario): ScenarioResult => {
220	  const results: StepResult[] = [];
221	  const policies = new Map<number, Policy>();
222	  let hasQuoted = false;
223	
224	  scenario.steps.forEach((step, index) => {
225	    if (step.op === "quote") {
226	      results.push(quote(step.items, scenario.customer, hasQuoted));
227	      policies.set(index, openPolicy(step.items));
228	      hasQuoted = true;
229	
230	      return;
231	    }
232	
233	    results.push(claim(policies.get(step.policy)!, step.incident));
234	  });
235	
236	  return { results };
237	};
